<?php require_once __DIR__.'/bootstrap.php';$errors=[];$old=['name'=>'','category'=>'','price'=>'','stock'=>''];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old['name']=trim($_POST['name']??'');$old['category']=trim($_POST['category']??'');$old['price']=trim($_POST['price']??'');$old['stock']=trim($_POST['stock']??'');if(mb_strlen($old['name'])<3)$errors[]='Nama produk minimal 3 karakter.';if($old['category']==='')$errors[]='Kategori wajib diisi.';if(!is_numeric($old['price'])||(float)$old['price']<=0)$errors[]='Harga harus lebih besar dari 0.';if(filter_var($old['stock'],FILTER_VALIDATE_INT)===false||(int)$old['stock']<0)$errors[]='Stok harus bilangan bulat 0 atau lebih.';if(!$errors){$check=$pdo->prepare('SELECT id FROM products WHERE name = ? LIMIT 1');$check->execute([$old['name']]);if($check->fetch())$errors[]='Nama produk sudah digunakan. Gunakan nama yang unik.';}if(!$errors){$stmt=$pdo->prepare('INSERT INTO products (name,category,price,stock) VALUES (?,?,?,?)');try{$stmt->execute([$old['name'],$old['category'],(float)$old['price'],(int)$old['stock']]);flash('success','Produk berhasil ditambahkan.');header('Location: index.php');exit;}catch(PDOException $e){$errors[]='Produk gagal disimpan. Pastikan nama produk unik.';}}}?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Tambah Produk — MELORA MART</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><div class="container nav-wrap"><a class="brand" href="index.php">MELORA MART</a></div></header><main class="container form-page"><a class="back" href="index.php">← Kembali ke daftar</a><div class="form-card"><p class="eyebrow">CREATE</p><h1>Tambah Produk</h1><p class="subtitle">Isi semua data produk dengan benar.</p><?php if($errors):?><div class="alert error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" novalidate><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Nama Produk <input type="text" name="name" value="<?=e($old['name'])?>" minlength="3" required placeholder="Contoh: Kemeja Linen"></label><label>Kategori <input type="text" name="category" value="<?=e($old['category'])?>" required placeholder="Contoh: Fashion"></label><label>Harga <input type="number" name="price" value="<?=e($old['price'])?>" min="0.01" step="0.01" required placeholder="129000"></label><label>Stok <input type="number" name="stock" value="<?=e($old['stock'])?>" min="0" step="1" required placeholder="10"></label><div class="form-actions"><a class="btn btn-muted" href="index.php">Batal</a><button class="btn btn-primary" type="submit">Simpan Produk</button></div></form></div></main></body></html>
